class Solution { public String reorderSpaces(String text){int spaces=0;for(char value:text.toCharArray())if(value==' ')spaces++;String trimmed=text.trim();String[] words=trimmed.isEmpty()?new String[0]:trimmed.split(" +");int gap=words.length<=1?0:spaces/(words.length-1),tail=spaces-gap*Math.max(0,words.length-1);String separator=" ".repeat(gap);return String.join(separator,words)+" ".repeat(tail);} }
